/**
 * The before/after proof for `igris fix`: the patched fixture
 * (fixtures/leaky-dapp-fixed, generated by `igris fix --write`) no longer
 * leaks the address to the RPC provider, and the scan detects Anon-RPC usage
 * from the harness's bootstrap read through the wallet.
 *
 * The other three planted leaks (analytics/error-monitor/pixel) are NOT RPC
 * traffic and stay — `igris fix` honestly fixes only what it claims to fix.
 */
import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import type { Server } from 'node:http';
import { join } from 'node:path';
import type { Report } from '@igris/core';
import { scan } from '../src/index.js';
import {
  buildFixture,
  HOST_RULES,
  PAGE_PORT,
  REPO_ROOT,
  serveDist,
  startSinkServer,
} from './helpers.js';

const FIXTURE = join(REPO_ROOT, 'fixtures/leaky-dapp-fixed');
const FIXED_PAGE_PORT = PAGE_PORT + 2; // own port: avoid cross-file conflicts

let pageServer: Server;
let sink: { close: () => Promise<void> };

async function scanVariant(variant: string): Promise<Report> {
  return scan({
    url: `http://leaky-dapp.test:${FIXED_PAGE_PORT}/?variant=${variant}`,
    hostResolverRules: HOST_RULES,
    dwellMs: 2500, // the anon-rpc harness needs a moment to attempt bootstrap
  });
}

beforeAll(async () => {
  buildFixture(FIXTURE);
  pageServer = await serveDist(join(FIXTURE, 'dist'), FIXED_PAGE_PORT);
  sink = await startSinkServer();
}, 180_000);

afterAll(async () => {
  await new Promise((r) => pageServer.close(() => r(undefined)));
  await sink.close();
});

describe.each(['viem', 'ethers', 'wagmi'] as const)('fixed fixture, %s variant', (variant) => {
  it(
    'no address reaches any RPC provider, and Anon-RPC usage is detected',
    async () => {
      const report = await scanVariant(variant);
      expect(report.status).toBe('completed');

      const rpcLeaks = report.findings.filter((f) => f.class === 'rpc-provider');
      expect(rpcLeaks, JSON.stringify(rpcLeaks, null, 2)).toEqual([]);

      // No traffic to the RPC sink host at all.
      const rpcContacts = report.thirdParties.filter((t) => t.class === 'rpc-provider');
      expect(rpcContacts).toEqual([]);

      // The harness's one bootstrap eth_call went through our mock wallet.
      expect(report.usesAnonRpc).toBe(true);

      // The non-RPC leaks are untouched (igris fix fixes RPC reads, nothing else).
      expect(report.findings.some((f) => f.class === 'analytics')).toBe(true);
    },
    180_000,
  );
});
